BEN=734efb6bc407c691c3d7d99e29b710544c82a9c5; S08=3c0fa97090afb2c0fca41898774db7247e23e522; S05=eb7233e3646640397f14e360f601aeff088d7536
W=${*:-s04 s07 s06 benny s08 s05 lead07 lead06}
for x in $W; do case $x in
  s04)    need $S04 claude/rainbow-s04-match-c21;   mk s04 /home/user/wt/s04 claude/rainbow-s04-match-c28 $S04 backups/wip/claude__rainbow-s04-match-c27 ;;
  s07)    need $S07 claude/rainbow-s07-match-c18;   mk s07 /home/user/wt/s07 claude/rainbow-s07-match-c28 $S07 backups/wip/claude__rainbow-s07-match-c27 ;;
  s06)    need $S06 claude/rainbow-s06-match-c23;   mk s06 /home/user/wt/s06 claude/rainbow-s06-match-c28 $S06 backups/wip/claude__rainbow-s06-match-c27 ;;
  benny)  need $BEN claude/rainbow-benny-c23;       mk benny /home/user/wt/benny claude/rainbow-benny-c28 $BEN backups/wip/claude__rainbow-benny-c27 ;;
  s08)    need $S08 claude/rainbow-s08-scenery-c17; mk s08 /home/user/wt/s08 claude/rainbow-s08-scenery-c28 $S08 backups/wip/claude__rainbow-s08-scenery-c27 ;;
  s05)    need $S05 claude/rainbow-s05-match-c19;   mk s05 /home/user/wt/s05 claude/rainbow-s05-match-c28 $S05 backups/wip/claude__rainbow-s05-match-c27 ;;
  lead07) need $S07 claude/rainbow-s07-match-c18;   mk lead07 /home/user/wt/lead07 --detach $S07 backups/wip/detached-8accdad0a0 ;;
  lead06) need $S06 claude/rainbow-s06-match-c23;   mk lead06 /home/user/wt/lead06 --detach $S06 backups/wip/detached-e162aec2bf ;;
esac; done

